from django.db import migrations


def chosen_to_colleagues(apps, schema_editor):
    """Pieces shown to chosen workspaces and spaces: to the people one works with."""
    UserProfile = apps.get_model("core", "UserProfile")
    for profile in UserProfile.objects.exclude(visibility={}):
        visibility = dict(profile.visibility or {})
        changed = False
        for field, setting in visibility.items():
            if isinstance(setting, dict) and setting.get("level") == "selected":
                visibility[field] = {**setting, "level": "colleagues"}
                changed = True
        if changed:
            profile.visibility = visibility
            profile.save(update_fields=["visibility"])


